/* Tekrar havuzu: rel-pronoun, rel-prep, rel-reduction, noun-clause, ger-inf, comp */
PRACTICE.push(
  {id:"r-rel-pronoun-01", sub:"rel-pronoun", from:["clauses-01","w3-12"], q:"Gregor Mendel, ---- experiments with pea plants laid the foundations of modern genetics, was largely ignored by the scientific community during his lifetime.", o:["who","whose","whom","which","that"], a:1, e:"Boşluktan sonra gelen “experiments” isminin sahibi Mendel'dir; iyelik bildiren whose gerekir. who ardından doğrudan fiil ister, oysa “experiments” zaten özne olduğundan cümle bozulur; that virgüllü yapıda kullanılamaz."},
  {id:"r-rel-pronoun-02", sub:"rel-pronoun", from:["clauses-02","w3-08"], q:"The Dead Sea, ---- lies more than 400 metres below sea level, has been shrinking by about one metre a year because of water extraction.", o:["where","that","what","which","whose"], a:3, e:"Virgüllü (non-defining) yapıda cansız bir isim niteleniyor ve boşluktan sonra öznesi eksik bir yüklem (lies) var: which. that virgüllü yapıda kullanılamaz; where ise ardından tam cümle ister."},
  {id:"r-rel-pronoun-03", sub:"rel-pronoun", from:["clauses-03"], q:"The period ---- the Black Death swept across Europe in the mid-fourteenth century saw the population of some cities fall by half.", o:["when","which","whose","where","whom"], a:0, e:"Nitelenen isim bir zaman ifadesi (period) ve boşluktan sonra tam bir cümle (the Black Death swept …) geliyor: when. which ardından öznesi ya da nesnesi eksik bir yapı isterdi; where yer bildirir."},
  {id:"r-rel-pronoun-04", sub:"rel-pronoun", from:["clauses-04"], q:"The volunteers, ---- the researchers had selected from more than 3,000 applicants, spent six months in an isolated habitat simulating life on Mars.", o:["who","which","whose","that","whom"], a:4, e:"“the researchers had selected ----” yapısında gönüllüler “selected” fiilinin nesnesidir; insan + nesne konumu whom ister. which insanlar için kullanılmaz; that ise virgüllü yapıda kullanılamaz."},
  {id:"r-rel-pronoun-05", sub:"rel-pronoun", from:["clauses-03"], q:"Health officials have identified several regions ---- the disease is still widespread despite decades of vaccination campaigns.", o:["which","when","where","whom","what"], a:2, e:"Nitelenen isim bir yer (regions) ve boşluktan sonra tam bir cümle (the disease is still widespread) geliyor: where. which ardından eksik öğeli bir yapı ister; when zaman ifadeleri içindir."},
  {id:"r-rel-pronoun-06", sub:"rel-pronoun", from:["clauses-02","clauses-04"], q:"Kyoto, ---- millions of tourists visit each autumn to see the changing leaves, was the imperial capital of Japan for more than a thousand years.", o:["where","when","whose","which","who"], a:3, e:"“visit” geçişli bir fiildir ve nesnesi eksiktir (tourists visit Kyoto); eksik nesnenin yerini tutan which gerekir. Yer ismi görünce seçilen where ardından eksiksiz bir cümle isterdi, bu yüzden en tehlikeli çeldiricidir."},
  {id:"r-rel-pronoun-07", sub:"rel-pronoun", from:["clauses-02","w3-08"], q:"The central bank raised interest rates for the fifth time in a single year, ---- led many analysts to predict a sharp slowdown in the housing market.", o:["which","that","what","who","it"], a:0, e:"Virgülden sonra gelen which, önceki cümlenin tamamını (faizlerin beşinci kez artırılmasını) niteleyebilir ve “led” fiilinin öznesi olur. that virgüllü yapıda kullanılamaz; it ise bağlaç olmadığı için iki cümleyi virgülle bağlayamaz."},
  {id:"r-rel-pronoun-08", sub:"rel-pronoun", from:["clauses-02","clauses-01"], q:"Patients ---- take the drug for more than a year may experience mild liver problems and should be monitored regularly.", o:["which","whose","who","whom","where"], a:2, e:"Nitelenen isim insan (patients) ve boşluktan sonra öznesi eksik bir yüklem (take) var: who. whom nesne konumu içindir; which ise insanlar için kullanılmaz."},
  {id:"r-rel-pronoun-09", sub:"rel-pronoun", from:["clauses-01","w3-12"], q:"Pompeii, ---- ruins were buried under volcanic ash in AD 79, offers a remarkably detailed picture of daily life in the Roman Empire.", o:["which","where","that","when","whose"], a:4, e:"“ruins” isminin sahibi Pompeii'dir; iyelik bildiren whose cansız isimler için de kullanılır. which ve where ardından “ruins were buried” gibi tam bir cümle almaz, bu yapıda iyelik anlamı kurulamaz."},
  {id:"r-rel-pronoun-10", sub:"rel-pronoun", from:["clauses-03"], q:"Many historians regard 1453, ---- Constantinople fell to the Ottomans, as the symbolic end of the Middle Ages.", o:["which","when","that","where","what"], a:1, e:"Nitelenen ifade bir yıl ve boşluktan sonra tam bir cümle (Constantinople fell …) geliyor: when. which ardından eksik öğeli bir yapı isterdi; that ise virgüllü yapıda kullanılamaz."},
  {id:"r-rel-pronoun-11", sub:"rel-pronoun", from:["clauses-02","w3-08","clauses-01"], q:"The engineer ---- designed the bridge insisted that the steel cables, ---- had been imported from Germany, should be tested again before the opening.", o:["who / which","which / that","whom / which","whose / which","who / that"], a:0, e:"İlk boşlukta insan + öznesi eksik yüklem (designed) olduğu için who; ikinci boşlukta virgüllü yapıda cansız isim (cables) niteleniyor: which. that virgüllü yapıda kullanılamaz; whom ise özne konumunda kullanılmaz."},
  {id:"r-rel-pronoun-12", sub:"rel-pronoun", from:["w3-12","clauses-01"], passage:"Ada Lovelace, (1) ---- notes on Charles Babbage's Analytical Engine included what is now regarded as the first computer program, was the daughter of the poet Lord Byron. Although the machine was never built, she recognised that it could do far more than simple calculations. She even suggested that such a device might one day compose music, an idea that was more than a century ahead of its time.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["who","which","whom","that","whose"], a:4, e:"Boşluktan sonra gelen “notes” isminin sahibi Lovelace'tır; iyelik bildiren whose gerekir. who ardından doğrudan fiil ister, oysa “notes” zaten öznedir; that ise virgüllü yapıda kullanılamaz."},
  {id:"r-rel-pronoun-13", sub:"rel-pronoun", from:["clauses-03"], passage:"In the third century BC, Alexandria was the intellectual capital of the Mediterranean world. It was a city (1) ---- scholars from Greece, Egypt and the Near East gathered to study mathematics, astronomy and medicine. Its famous library is said to have held hundreds of thousands of scrolls, and scholars working there made important advances, such as estimating the circumference of the Earth.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["which","where","who","when","whose"], a:1, e:"Nitelenen isim bir yer (a city) ve boşluktan sonra eksiksiz bir cümle (scholars … gathered) geliyor: where. “gather” burada nesne almadığı için which kullanılamaz; when ise zaman bildirir."},
  {id:"r-rel-pronoun-14", sub:"rel-pronoun", from:["w3-08","clauses-02"], passage:"The printing press, (1) ---- Johannes Gutenberg developed around 1440, dramatically reduced the cost of producing books. Before its invention, texts had to be copied by hand, a process that could take months. Within fifty years, printing shops had appeared in more than two hundred European cities, and millions of books were in circulation.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["that","where","who","which","whose"], a:3, e:"Virgüllü yapıda cansız bir isim (the printing press) niteleniyor ve “developed” fiilinin nesnesi eksik: which. that anlamca uysa da virgüllü yapıda kullanılamaz; where ardından tam cümle isterdi."},
  {id:"r-rel-pronoun-15", sub:"rel-pronoun", from:["clauses-03"], q:"Scientists are still investigating the reason ---- some people remain healthy into their nineties while others develop chronic diseases much earlier.", o:["which","what","why","whose","how"], a:2, e:"“the reason” isminden sonra tam bir cümle gelirse why kullanılır (the reason why). which ardından eksik öğeli bir yapı isterdi; “the reason how” diye bir kalıp yoktur."},
  {id:"r-rel-pronoun-16", sub:"rel-pronoun", from:["clauses-04","clauses-02"], q:"The candidate ---- the committee believes is best qualified for the post will be announced at the end of next week.", o:["whom","whose","who","which","what"], a:2, e:"“the committee believes” araya giren bir ifadedir; asıl yapı “the candidate who is best qualified” olduğundan boşluk “is” fiilinin öznesidir: who. “believes” fiilinden sonra geldiği için nesne sanılıp whom seçilmesi tipik bir tuzaktır."},
  {id:"r-rel-pronoun-17", sub:"rel-pronoun", from:["clauses-02"], q:"All the data ---- the team collected during the two-year expedition were lost when the laboratory's main server failed.", o:["what","who","where","whose","that"], a:4, e:"Virgülsüz (defining) yapıda “collected” fiilinin nesnesi eksik ve nitelenen şey cansız: that. what kendi başına “the thing that” anlamı taşıdığı için bir isimden (data) sonra kullanılamaz."},
  {id:"r-rel-pronoun-18", sub:"rel-pronoun", from:["clauses-02"], q:"The museum ---- houses the largest collection of dinosaur fossils in Asia is located in the north of the city.", o:["which","where","when","whose","what"], a:0, e:"Boşluktan sonra öznesi eksik bir yüklem (houses) var; bu yüzden which. Nitelenen isim bir yer olsa da where ardından tam cümle isterdi, burada özne eksiktir."},
  {id:"r-rel-pronoun-19", sub:"rel-pronoun", from:["clauses-03"], q:"Many economists refer to 2008 as the year ---- changed the global financial system for ever.", o:["when","which","where","whose","whom"], a:1, e:"Nitelenen isim zaman ifadesi olsa da boşluktan sonra öznesi eksik bir yüklem (changed) var: which. when ardından tam bir cümle (özne + yüklem) isterdi, bu yüzden en çekici çeldiricidir."},
  {id:"r-rel-pronoun-20", sub:"rel-pronoun", from:["clauses-01","w3-12"], q:"Researchers interviewed dozens of farmers ---- crops had been destroyed by the unusually heavy rains of the previous spring.", o:["who","which","whom","whose","where"], a:3, e:"Boşluktan sonra gelen “crops” isminin sahibi çiftçilerdir; iyelik bildiren whose gerekir. who ardından doğrudan fiil ister, oysa “crops” zaten özne olduğundan cümle bozulur."},
  {id:"r-rel-pronoun-21", sub:"rel-pronoun", from:["clauses-02","clauses-04"], q:"Florence Nightingale, ---- transformed nursing into a respected profession, used statistics to prove that poor hygiene was killing more soldiers than battle wounds.", o:["whom","which","whose","that","who"], a:4, e:"Nitelenen isim insan ve boşluktan sonra öznesi eksik bir yüklem (transformed) var: who. whom nesne konumu içindir; that virgüllü yapıda kullanılamaz."},
  {id:"r-rel-pronoun-22", sub:"rel-pronoun", from:["clauses-03"], q:"Economists warn that the country could soon face a situation ---- prices rise faster than wages for several consecutive years.", o:["which","where","what","whom","whose"], a:1, e:"“situation, case, point” gibi soyut isimlerden sonra tam bir cümle gelirse where kullanılır (a situation where = in which). which ardından eksik öğeli bir yapı isterdi."},
  {id:"r-rel-pronoun-23", sub:"rel-pronoun", from:["clauses-04","clauses-01"], q:"The engineer ---- the company recruited last year has designed a battery ---- charging time is half that of existing models.", o:["who / which","whose / whom","which / whose","whom / whose","whom / that"], a:3, e:"İlk boşlukta insan “recruited” fiilinin nesnesidir: whom; ikinci boşlukta “charging time” pilin şarj süresidir, iyelik bildiren whose gerekir. which ve that ardından “charging time is …” gibi tam bir cümle alamaz."},
  {id:"r-rel-pronoun-24", sub:"rel-pronoun", from:["clauses-02","w3-08"], q:"The Rosetta Stone, ---- was discovered by French soldiers in 1799, provided the key to deciphering Egyptian hieroglyphs.", o:["which","that","who","where","what"], a:0, e:"Virgüllü yapıda cansız bir isim niteleniyor ve boşluktan sonra öznesi eksik bir yüklem (was discovered) var: which. that virgüllü yapıda kullanılamaz; where ardından tam cümle isterdi."},
  {id:"r-rel-pronoun-25", sub:"rel-pronoun", from:["clauses-02"], q:"Everything ---- the witnesses told the police turned out to be consistent with the forensic evidence.", o:["what","who","that","whose","where"], a:2, e:"everything, all, nothing gibi belgisiz zamirlerden sonra defining yapıda that kullanılır; “told” fiilinin nesnesi eksiktir. “everything what” yanlıştır, çünkü what zaten “the thing that” anlamını içerir."},
  {id:"r-rel-pronoun-26", sub:"rel-pronoun", from:["clauses-03"], q:"The experiment will be repeated next spring, ---- temperatures in the region are more stable and the soil is less frozen.", o:["when","which","where","that","what"], a:0, e:"Zaman ifadesi (next spring) niteleniyor ve boşluktan sonra tam bir cümle geliyor: when. which ardından eksik öğeli bir yapı isterdi; that ise virgüllü yapıda kullanılamaz."},
  {id:"r-rel-pronoun-27", sub:"rel-pronoun", from:["clauses-02","w3-08"], passage:"In 1928, Alexander Fleming returned from holiday to find that one of his bacterial cultures had been contaminated by a mould. Around the mould, the bacteria had been destroyed. Fleming, (1) ---- had been searching for an effective antibacterial substance for years, immediately realised the importance of this observation. It took more than a decade, however, before other scientists found a way to produce penicillin in large quantities.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["which","whom","whose","who","that"], a:3, e:"Virgüllü yapıda insan niteleniyor ve boşluktan sonra öznesi eksik bir yüklem (had been searching) var: who. whom nesne konumu içindir; that virgüllü yapıda, which ise insanlar için kullanılmaz."},
  {id:"r-rel-prep-01", sub:"rel-prep", from:["clauses-05","w3-02"], q:"Economists are trying to determine the extent ---- rising interest rates have slowed consumer spending.", o:["which","in that","to which","what","for whom"], a:2, e:"“to some extent / to what extent” kalıbı nedeniyle edat + which gerekir: the extent to which. Boşluktan sonraki cümle eksiksiz olduğu için tek başına which kullanılamaz; edattan sonra that gelmez."},
  {id:"r-rel-prep-02", sub:"rel-prep", from:["clauses-05","w3-02"], q:"The speed ---- the polar ice sheets are melting has alarmed climate scientists around the world.", o:["which","at that","what","with whom","at which"], a:4, e:"“melt at a speed” kalıbı nedeniyle edat + which gerekir: at which. Cümle tam olduğundan tek başına which olmaz; edattan sonra that kullanılamaz."},
  {id:"r-rel-prep-03", sub:"rel-prep", from:["clauses-06"], q:"The national library holds over 5,000 manuscripts, ---- date from before the twelfth century.", o:["some of them","some of which","some of whom","which some","some which"], a:1, e:"Virgülden sonra iki cümleyi bağlayacak bir relative gerekir; el yazmaları cansız olduğu için some of which. “some of them” bağlaç olmadığı için iki tam cümleyi virgülle bağlayamaz; some of whom insanlar içindir."},
  {id:"r-rel-prep-04", sub:"rel-prep", from:["clauses-06"], q:"The study followed 400 elderly patients, ---- had been diagnosed with early-stage dementia.", o:["half of whom","half of them","half of which","whom half","half whom"], a:0, e:"Virgülden sonra bağlaç görevi gören bir yapı gerekir; hastalar insan olduğu için half of whom. “half of them” zamirdir ve iki cümleyi bağlayamaz; half of which cansızlar içindir."},
  {id:"r-rel-prep-05", sub:"rel-prep", from:["clauses-05","clauses-07"], q:"The treaty clearly established the conditions ---- the two countries would share the water of the river.", o:["which","under that","in whom","under which","what"], a:3, e:"“under certain conditions” kalıbı nedeniyle edat + which gerekir: under which. Boşluktan sonraki cümle tam olduğu için tek başına which olmaz; edattan sonra that, cansızlar için whom kullanılamaz."},
  {id:"r-rel-prep-06", sub:"rel-prep", from:["clauses-05"], q:"The professor ---- I sent my application three weeks ago has not replied yet.", o:["which","to that","who","to which","to whom"], a:4, e:"“send something to someone” kalıbı ve insan (professor) olduğu için to whom gerekir. “who” edatı (to) karşılamadığı için cümle eksik kalır; edattan sonra that gelmez, which ise insanlar için kullanılmaz."},
  {id:"r-rel-prep-07", sub:"rel-prep", from:["clauses-06","clauses-08"], q:"The two candidates, neither ---- had any previous experience in government, promised sweeping economic reforms.", o:["of them","of whom","of which","whom","who"], a:1, e:"neither of + whom yapısı virgüllü bir relative clause kurar; adaylar insan olduğu için of whom. “neither of them” iki tam cümleyi bağlayamaz; of which ise cansızlar içindir."},
  {id:"r-rel-prep-08", sub:"rel-prep", from:["clauses-06"], q:"Scientists analysed more than two hundred water samples from the river, none ---- showed any trace of contamination.", o:["of whom","of them","which","of which","that"], a:3, e:"Örnekler cansız olduğu için “none of which” gerekir ve bu yapı iki cümleyi virgülle bağlar. “none of them” bağlaç değildir; of whom ise insanlar içindir."},
  {id:"r-rel-prep-09", sub:"rel-prep", from:["clauses-08","clauses-06"], q:"The company launched three new products last year, the most successful ---- was a low-cost water filter for rural households.", o:["of which","which","of them","of whom","whose"], a:0, e:"“the most successful of the products” anlamı virgüllü yapıda “the most successful of which” ile verilir. “of them” bağlaç olmadığı için iki cümleyi bağlayamaz; whose ismin önüne gelir, arkasına gelemez."},
  {id:"r-rel-prep-10", sub:"rel-prep", from:["clauses-07"], q:"The village ---- the poet spent his childhood has been turned into an open-air museum.", o:["which","whom","in which","that","on whom"], a:2, e:"Boşluktan sonraki cümle (the poet spent his childhood) eksiksizdir; yer bildiren in which (= where) gerekir. which ve that ardından eksik öğeli bir yapı isterdi."},
  {id:"r-rel-prep-11", sub:"rel-prep", from:["clauses-05","clauses-08"], q:"Farmers in the region depend entirely on the monsoon rains, without ---- their crops would fail.", o:["that","which","it","whom","them"], a:1, e:"Edattan (without) sonra cansız isim için yalnızca which gelir. that edattan sonra kullanılamaz; “it” ise zamir olduğundan iki cümleyi bağlayamaz."},
  {id:"r-rel-prep-12", sub:"rel-prep", from:["clauses-05"], q:"The engineers ---- the success of the entire mission depended worked around the clock for three days.", o:["on whom","on which","whom","who","on that"], a:0, e:"“depend on someone” kalıbı ve nitelenen isim insan olduğu için on whom gerekir. whom/who tek başına edatı karşılamaz; on which cansızlar için kullanılır, edattan sonra that gelmez."},
  {id:"r-rel-prep-13", sub:"rel-prep", from:["clauses-08"], q:"The ancient manuscript, the author ---- remains unknown, describes a solar eclipse in remarkable detail.", o:["whose","of whom","of which","which","that"], a:2, e:"“the author of the manuscript” anlamı isimden sonra “the author of which” ile verilir. whose ismin önüne gelir (whose author), isimden sonra kullanılamaz; of whom ise insanlar içindir."},
  {id:"r-rel-prep-14", sub:"rel-prep", from:["clauses-08"], q:"The river, ---- water was once too polluted to support any fish, now has a thriving salmon population.", o:["of which","which","that","of whose","whose"], a:4, e:"Boşluktan hemen sonra bir isim (water) geldiği için iyelik bildiren whose gerekir. of which yapısı ismin arkasına gelir (the water of which); ismin önünde kullanılamaz."},
  {id:"r-rel-prep-15", sub:"rel-prep", from:["clauses-05","w3-02"], passage:"Fermentation is one of the oldest techniques (1) ---- humans have preserved food. Long before scientists understood the role of microorganisms, people in many cultures were making bread, cheese, yoghurt and pickled vegetables. Today, researchers are rediscovering fermented foods because of their possible benefits for digestive health.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["which","by whom","that","by which","what"], a:3, e:"“preserve food by a technique” kalıbı nedeniyle edat + which gerekir: by which. Boşluktan sonraki cümle eksiksiz olduğu için tek başına which ya da that kullanılamaz; by whom insanlar içindir."},
  {id:"r-rel-prep-16", sub:"rel-prep", from:["clauses-06"], passage:"Antarctica has no permanent population, but it hosts around seventy research stations run by nearly thirty countries. These stations, (1) ---- are staffed throughout the year, allow scientists to study everything from climate change to the behaviour of penguins. During the long polar winter, however, the number of people on the continent falls to around one thousand.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["around forty of them","around forty of whom","around forty which","around forty of which","which around forty of"], a:3, e:"Virgüllü yapıda istasyonlar (cansız) niteleniyor ve cümleler bağlanmalı: around forty of which. “of them” bağlaç değildir; of whom ise insanlar içindir."},
  {id:"r-rel-prep-17", sub:"rel-prep", from:["clauses-05","clauses-07"], passage:"Many parents wonder whether their children should start learning a foreign language early. Studies suggest that the age (1) ---- children begin learning a second language strongly influences how native-like their pronunciation becomes. Grammar and vocabulary, on the other hand, can be learned successfully at almost any age.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["at which","which","at that","what","whose"], a:0, e:"“begin something at an age” kalıbı nedeniyle edat + which gerekir: at which. Boşluktan sonraki cümle tam olduğu için tek başına which olmaz; edattan sonra that gelmez."},
  {id:"r-rel-prep-18", sub:"rel-prep", from:["clauses-06"], q:"More than 200 volunteers, all ---- had completed a first-aid course, were sent to the areas affected by the floods.", o:["of them","of whom","of which","who","whom"], a:1, e:"Gönüllüler insan olduğu için “all of whom” gerekir ve bu yapı virgüllü relative clause kurar. “all of them” iki cümleyi bağlayamaz; of which cansızlar içindir."},
  {id:"r-rel-prep-19", sub:"rel-prep", from:["clauses-06"], q:"The laboratory has two electron microscopes, both ---- were purchased with funding from the European Union.", o:["of them","of whom","of which","which","that"], a:2, e:"Mikroskoplar cansız olduğu için “both of which” gerekir; bu yapı virgülden sonra iki cümleyi bağlar. “both of them” zamirdir, bağlaç görevi göremez."},
  {id:"r-rel-prep-20", sub:"rel-prep", from:["clauses-05"], q:"The business partner with ---- she founded the company later became her main competitor.", o:["that","who","which","whose","whom"], a:4, e:"Edattan (with) sonra insan için yalnızca whom kullanılır. Edattan sonra who ve that gelemez; which ise cansızlar içindir."},
  {id:"r-rel-prep-21", sub:"rel-prep", from:["clauses-05","w3-02"], q:"The ease ---- misinformation spreads on social media has become a major concern for public health authorities.", o:["with which","which","by that","with whom","what"], a:0, e:"“with ease” kalıbı nedeniyle edat + which gerekir: the ease with which. Cümle tam olduğu için tek başına which olmaz; with whom insanlar içindir."},
  {id:"r-rel-prep-22", sub:"rel-prep", from:["clauses-05"], q:"The documents ---- the historian based her conclusions were later shown to be nineteenth-century forgeries.", o:["which","on that","on which","on whom","where"], a:2, e:"“base something on something” kalıbı nedeniyle edat + which gerekir: on which. Tek başına which edatı karşılamaz; edattan sonra that kullanılamaz; on whom ise insanlar içindir."},
  {id:"r-rel-prep-23", sub:"rel-prep", from:["clauses-06"], q:"The charity supports 1,200 refugees, many ---- arrived without any documents, and runs three shelters, none ---- has adequate heating.", o:["of which / of whom","of them / of which","of whom / of them","whom / which","of whom / of which"], a:4, e:"Mülteciler insan olduğu için many of whom, barınaklar cansız olduğu için none of which gerekir. “of them” iki cümleyi bağlayamaz; edatsız whom/which ise miktar ifadesiyle kullanılamaz."},
  {id:"r-rel-prep-24", sub:"rel-prep", from:["clauses-05","clauses-08"], q:"The sum ---- the painting was sold at auction last month set a new record for a living artist.", o:["which","for which","for that","what","by whom"], a:1, e:"“sell something for a sum” kalıbı nedeniyle edat + which gerekir: for which. Cümle tam olduğu için tek başına which kullanılamaz; edattan sonra that gelmez."},
  {id:"r-rel-prep-25", sub:"rel-prep", from:["clauses-05"], q:"The patients ---- the new drug was tested reported fewer side effects than the researchers had expected.", o:["on which","whom","who","on whom","to that"], a:3, e:"“test a drug on someone” kalıbı ve nitelenen isim insan olduğu için on whom gerekir. whom/who tek başına edatı karşılamaz; on which ise cansızlar içindir."},
  {id:"r-rel-prep-26", sub:"rel-prep", from:["clauses-06","clauses-08"], q:"The report lists twelve recommendations, only three ---- have been implemented so far.", o:["of them","of which","of whom","which","that"], a:1, e:"Öneriler cansız olduğu için “only three of which” gerekir ve bu yapı virgülden sonra cümleleri bağlar. “of them” bağlaç değildir; of whom insanlar içindir."},
  {id:"r-rel-prep-27", sub:"rel-prep", from:["clauses-05","clauses-08"], q:"Charles Darwin is the scientist from ---- work most of our modern ideas about evolution are derived.", o:["whom","which","that","who","whose"], a:4, e:"“derive from the scientist's work” anlamı edat + whose + isim ile verilir: from whose work. Boşluktan sonra bir isim (work) geldiği için from whom ya da from which cümleyi bozar."},
  {id:"r-rel-reduction-01", sub:"rel-reduction", from:["clauses-10"], q:"Plastic particles ---- at depths of more than 10,000 metres suggest that pollution has reached even the most remote parts of the ocean.", o:["detecting","were detected","having detected","detected","to detect"], a:3, e:"Parçacıklar tespit edilir (pasif), bu yüzden “which were detected” V3 ile kısaltılır: detected. were detected cümlede ikinci bir çekimli fiil yaratır; detecting ise aktif anlam verir."},
  {id:"r-rel-reduction-02", sub:"rel-reduction", from:["clauses-09","w3-06"], q:"Companies ---- more than 250 people are now required by law to publish data on the gender pay gap.", o:["employing","employed","are employing","who employing","to employ"], a:0, e:"Şirketler işçi çalıştıran etken taraftır (which employ); aktif relative clause V-ing ile kısaltılır: employing. employed pasif anlam verir; are employing ise ikinci bir çekimli fiil yaratır."},
  {id:"r-rel-reduction-03", sub:"rel-reduction", from:["clauses-11"], q:"In 1963, Valentina Tereshkova became the first woman ---- into space.", o:["travelling","travelled","to travel","having travelled","who travelling"], a:2, e:"the first / the last / the only ifadelerinden sonra relative clause “to V” ile kısaltılır: the first woman to travel. travelling bu kalıba uymayan en çekici çeldiricidir."},
  {id:"r-rel-reduction-04", sub:"rel-reduction", from:["clauses-12"], q:"---- the contract, the two companies immediately began sharing their research data.", o:["Signed","Having signed","Having been signed","Being signed","To have signed"], a:1, e:"Şirketler önce sözleşmeyi imzalamış, sonra veri paylaşmaya başlamıştır; önceki aktif eylem Having V3 ile verilir. Having been signed ve Being signed pasif olduğu için imzalayan özneye (companies) uymaz."},
  {id:"r-rel-reduction-05", sub:"rel-reduction", from:["clauses-12"], q:"---- about the approaching storm, the fishermen decided to stay in port for another two days.", o:["Having warned","Warning","To warn","Being warning","Having been warned"], a:4, e:"Balıkçılar uyarılmıştır (pasif) ve bu eylem karardan öncedir: Having been warned. Having warned ve Warning aktif anlam vererek balıkçıları uyaran taraf yapar."},
  {id:"r-rel-reduction-06", sub:"rel-reduction", from:["clauses-10","w3-06"], q:"The Sydney Harbour Bridge, ---- in 1932, is still one of the widest long-span bridges in the world.", o:["completed","completing","was completed","having completed","to complete"], a:0, e:"Köprü tamamlanmıştır (pasif): which was completed → completed. was completed cümlede “is” dışında ikinci bir çekimli fiil yaratır; completing aktif anlam verir."},
  {id:"r-rel-reduction-07", sub:"rel-reduction", from:["clauses-09","w3-06"], q:"The number of people ---- in cities is expected to reach nearly seven billion by 2050.", o:["lived","to live","living","are living","who living"], a:2, e:"İnsanlar şehirlerde yaşayan etken taraftır (who live): living. “who living” hem pronoun hem -ing kullandığı için hatalıdır; are living cümlede ikinci bir çekimli fiil yaratır."},
  {id:"r-rel-reduction-08", sub:"rel-reduction", from:["clauses-10","w3-06"], passage:"The Great Wall of China is not a single wall but a series of fortifications (1) ---- over many centuries to protect Chinese states from invasions from the north. Its total length, including all its branches, is estimated at more than 20,000 kilometres. Contrary to popular belief, however, it cannot be seen with the naked eye from space.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["building","were built","having built","to build","built"], a:4, e:"Surlar inşa edilmiştir (pasif): which were built → built. were built cümlede ikinci bir çekimli fiil yaratır; building aktif anlam verir."},
  {id:"r-rel-reduction-09", sub:"rel-reduction", from:["w3-06","clauses-09"], passage:"Bees play a vital role in global agriculture. They are responsible for pollinating many of the crops (1) ---- the world's growing population, including apples, almonds and coffee. In recent years, however, bee populations have declined sharply in many regions, largely because of pesticides, disease and the loss of natural habitats.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["fed","feeding","are feeding","to be fed","having been fed"], a:1, e:"Mahsuller dünya nüfusunu besleyen etken taraftır (which feed): feeding. fed pasif anlam verir (beslenen mahsuller); are feeding ise ikinci bir çekimli fiil yaratır."},
  {id:"r-rel-reduction-10", sub:"rel-reduction", from:["clauses-11"], q:"The last person ---- the building at night must make sure that the alarm system has been switched on.", o:["leaving","left","having left","to leave","who leaving"], a:3, e:"the last / the first / the only ifadelerinden sonra relative clause “to V” ile kısaltılır: the last person to leave. leaving bu kalıba uymaz; “who leaving” ise hem pronoun hem -ing içerdiği için yanlıştır."},
  {id:"r-rel-reduction-11", sub:"rel-reduction", from:["clauses-11"], q:"Brazil is the only country ---- the FIFA World Cup five times.", o:["winning","won","to have won","having been won","who winning"], a:2, e:"the only ifadesinden sonra kısaltma “to V” ile yapılır; başarı geçmişte tamamlandığı için perfect infinitive: to have won. won çekimli fiil gibi davranır; having been won ise pasif anlam verir."},
  {id:"r-rel-reduction-12", sub:"rel-reduction", from:["clauses-10","clauses-09"], q:"The houses ---- on the site at the moment will be sold to first-time buyers at reduced prices.", o:["building","being built","having built","were built","to build"], a:1, e:"Evler şu anda inşa edilmektedir; süregelen pasif anlam (which are being built) “being V3” ile kısaltılır. building aktif anlam verir; were built ise hem geçmiş zaman hem ikinci çekimli fiildir."},
  {id:"r-rel-reduction-13", sub:"rel-reduction", from:["clauses-12","clauses-09"], q:"---- the survey data, the researchers found that most of the respondents ---- in rural areas lacked access to high-speed internet.", o:["Having been analysed / lived","Analysed / living","Having analysed / lived","Having analysed / living","To analyse / were living"], a:3, e:"Araştırmacılar önce verileri incelemiştir (önceki aktif eylem): Having analysed; katılımcılar kırsalda yaşayan etken taraftır: living. lived pasif kısaltma gibi okunur ve anlamı bozar; were living ise ikinci bir çekimli fiildir."},
  {id:"r-rel-reduction-14", sub:"rel-reduction", from:["clauses-10"], q:"Most of the energy ---- by the country still comes from coal-fired power stations.", o:["consumed","consuming","is consumed","having consumed","to consume"], a:0, e:"Enerji tüketilir (pasif): which is consumed → consumed. consuming aktif anlam verir; is consumed ise “comes” fiiliyle birlikte ikinci bir çekimli fiil yaratır."},
  {id:"r-rel-reduction-15", sub:"rel-reduction", from:["clauses-09"], q:"Travellers ---- from countries affected by the outbreak will have to undergo a brief health check at the airport.", o:["arrived","are arriving","to arrive","who arriving","arriving"], a:4, e:"Yolcular gelen etken taraftır (who arrive): arriving. arrived pasif kısaltma gibi okunur; “who arriving” hem pronoun hem -ing içerdiği için hatalıdır."},
  {id:"r-rel-reduction-16", sub:"rel-reduction", from:["clauses-11","clauses-10"], q:"Marie Curie was the first person ---- the Nobel Prize twice.", o:["awarding","to award","having awarded","who awarded","to be awarded"], a:4, e:"the first ifadesinden sonra kısaltma “to V” ile yapılır; ödül verilen kişi olduğu için pasif infinitive gerekir: to be awarded. to award aktif anlamla Curie'yi ödülü veren kişi yapar."},
  {id:"r-rel-reduction-17", sub:"rel-reduction", from:["clauses-12"], q:"---- the safety instructions carefully, the technician accidentally damaged the expensive equipment.", o:["Having not been read","Not having read","Not to be read","Not read","Not been reading"], a:1, e:"Teknisyenin talimatları önceden okumamış olması hasarın nedenidir; önceki aktif eylemin olumsuzu Not having V3 ile verilir. Having not been read pasif olduğu için teknisyene uymaz."},
  {id:"r-rel-reduction-18", sub:"rel-reduction", from:["clauses-10"], q:"A new study ---- in the journal Nature suggests that some trees can communicate with one another through underground fungal networks.", o:["publishing","was published","published","having published","to publish"], a:2, e:"Çalışma yayımlanır (pasif): which was published → published. was published cümlede “suggests” dışında ikinci bir çekimli fiil yaratır; publishing aktif anlam verir."},
  {id:"r-rel-reduction-19", sub:"rel-reduction", from:["w3-06","clauses-09"], q:"Many of the problems ---- the healthcare system today are the result of decades of underfunding.", o:["faced","are facing","to face","facing","having been faced"], a:3, e:"Sorunlar sağlık sistemini karşı karşıya bırakan etken taraftır (which face the system): facing. faced pasif anlam verir ve ardından nesne (the healthcare system) gelemez."},
  {id:"r-rel-reduction-20", sub:"rel-reduction", from:["clauses-12"], passage:"The Great Fire of London began in a bakery on Pudding Lane in September 1666 and burned for four days. (1) ---- by the flames, much of the medieval city had to be rebuilt from scratch. The architect Christopher Wren designed more than fifty new churches, including St Paul's Cathedral, which still dominates the city's skyline today.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["Having been destroyed","Destroying","Having destroyed","To destroy","Being destroying"], a:0, e:"Şehrin büyük bölümü yangında yok edilmiştir (pasif) ve bu yeniden inşadan öncedir: Having been destroyed. Having destroyed ve Destroying aktif anlamla şehri yok eden taraf yapar."},
  {id:"r-rel-reduction-21", sub:"rel-reduction", from:["clauses-10"], q:"The painting, ---- to be worth over $10 million, was stolen from the gallery last night.", o:["believing","believed","is believed","having believed","to believe"], a:1, e:"“which is believed to be worth” pasif yapısı V3 ile kısaltılır: believed. is believed cümlede ikinci bir çekimli fiil yaratır; believing ise tabloyu inanan taraf yapar."},
  {id:"r-rel-reduction-22", sub:"rel-reduction", from:["clauses-10","clauses-11"], q:"The remains of a ship ---- to one of the early Portuguese explorers were discovered off the coast of Oman.", o:["thinking to belong","was thought to belong","having thought to belong","thought to have belonged","to think belonging"], a:3, e:"“which was thought to have belonged” pasif yapısı V3 ile kısaltılır ve geminin sahipliği geçmişte kaldığı için perfect infinitive gelir: thought to have belonged. was thought cümlede ikinci bir çekimli fiil yaratır."},
  {id:"r-rel-reduction-23", sub:"rel-reduction", from:["clauses-10"], q:"Workers ---- in the factory before 1980 were exposed to dangerously high levels of asbestos.", o:["employed","employing","were employed","to employ","having employed"], a:0, e:"İşçiler istihdam edilmiştir (pasif): who were employed → employed. were employed cümlede ikinci bir çekimli fiil yaratır; employing aktif anlamla işçileri işveren yapar."},
  {id:"r-rel-reduction-24", sub:"rel-reduction", from:["clauses-11"], q:"In 1990, Finland became the first country in the world ---- a carbon tax.", o:["introducing","introduced","to introduce","having introduced","who introduced"], a:2, e:"the first ifadesinden sonra relative clause “to V” ile kısaltılır: the first country to introduce. introducing bu kalıba uymaz; “who” ise ülkeler için kullanılmaz."},
  {id:"r-rel-reduction-25", sub:"rel-reduction", from:["clauses-10","w3-06"], q:"Minoxidil, ---- originally to treat high blood pressure, is now widely prescribed for hair loss.", o:["developing","was developed","having developed","to develop","developed"], a:4, e:"İlaç geliştirilmiştir (pasif): which was developed → developed. was developed ikinci bir çekimli fiil yaratır; developing ve having developed ilacı geliştiren taraf yapar."},
  {id:"r-rel-reduction-26", sub:"rel-reduction", from:["clauses-12"], q:"---- in the Arctic for more than two years, the members of the expedition were eager to return home.", o:["Having been lived","Lived","Having lived","To live","Being lived"], a:2, e:"Kuzey Kutbu'nda iki yıl geçirmek, eve dönme isteğinden önceki aktif bir eylemdir: Having lived. “live” nesne almayan bir fiil olduğu için Having been lived ve Being lived gibi pasif biçimler kurulamaz."},
  {id:"r-rel-reduction-27", sub:"rel-reduction", from:["w3-06","clauses-09"], passage:"The Amazon is the largest river in the world by volume. It discharges an enormous amount of water into the Atlantic Ocean, (1) ---- about one fifth of all the fresh water that flows into the world's oceans. So powerful is its flow that fresh water can be found far out at sea, well beyond the river's mouth.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["accounting for","accounted for","accounts for","to account for","having been accounted for"], a:0, e:"Virgülden sonraki yapı “which accounts for” anlamında aktif bir kısaltmadır: accounting for. accounts for iki cümleyi bağlaçsız birleştirir; accounted for ise pasif anlam verir."},
  {id:"r-noun-clause-01", sub:"noun-clause", from:["clauses-13"], q:"---- the universe will continue to expand for ever remains one of the central questions of modern cosmology.", o:["If","What","That","Which","Whether"], a:4, e:"“one of the central questions” belirsizlik bildirir; özne konumundaki noun clause için whether gerekir. if özne konumunda cümle başında kullanılamaz; What ardından eksik öğeli bir cümle isterdi."},
  {id:"r-noun-clause-02", sub:"noun-clause", from:["clauses-14"], q:"It is still not known ---- caused the sudden collapse of the bee colonies in the region last summer.", o:["that","what","whether","why","how"], a:1, e:"“caused” fiilinin öznesi eksiktir; hem özne olabilen hem de noun clause başlatan what (= the thing that) gerekir. that, whether, why ve how ardından tam bir cümle isterdi."},
  {id:"r-noun-clause-03", sub:"noun-clause", from:["clauses-16"], q:"The jury will award the prize to ---- of the two designs uses less energy.", o:["whoever","whatever","which","whichever","whether"], a:3, e:"İki seçenek arasından seçim anlatıldığı için whichever (hangisi … ise) gerekir. whoever insanlar içindir; which ise öncül isim olmadan edattan sonra noun clause başlatamaz."},
  {id:"r-noun-clause-04", sub:"noun-clause", from:["w3-11","clauses-14"], q:"Researchers are trying to find out ----.", o:["how long can the virus survive on different surfaces","how long does the virus survive on different surfaces","how long the virus can survive on different surfaces","that how long the virus survives on surfaces","which the virus can survive long on surfaces"], a:2, e:"Noun clause içinde soru kelimesinden sonra düz cümle sırası (özne + yüklem) kullanılır: how long the virus can survive. Devrik sıra (can the virus / does the virus) yalnızca doğrudan sorularda kullanılır."},
  {id:"r-noun-clause-05", sub:"noun-clause", from:["clauses-15"], q:"Despite ---- the region receives very little rainfall, farmers there produce large quantities of fruit.", o:["the fact that","that","what","although","whether"], a:0, e:"Edattan (despite) sonra tam bir cümle getirmek için the fact that gerekir; that tek başına edattan sonra gelemez. although bir bağlaçtır, despite ile birlikte kullanılamaz."},
  {id:"r-noun-clause-06", sub:"noun-clause", from:["clauses-13"], q:"The investigation focused on ---- the pilots had received adequate training before the flight.", o:["if","whether","that","what","which"], a:1, e:"Belirsizlik bildiren ve edattan (on) sonra gelen noun clause için whether kullanılır; edattan sonra if gelmez. that de edattan sonra tek başına kullanılamaz."},
  {id:"r-noun-clause-07", sub:"noun-clause", from:["w3-11"], q:"---- the ancient Egyptians moved such huge stone blocks without iron tools continues to fascinate engineers.", o:["What","Which","Whoever","How","Because"], a:3, e:"Boşluktan sonra tam bir cümle var ve anlam “nasıl” sorusuna işaret ediyor: How. What ardından eksik öğeli bir cümle isterdi; Because ise zarf cümleciği başlatır ve özne olamaz."},
  {id:"r-noun-clause-08", sub:"noun-clause", from:["clauses-16"], q:"---- is found responsible for the data breach will face criminal charges.", o:["Whoever","Whomever","Who","Whatever","Anyone"], a:0, e:"“is found” fiilinin öznesi eksik ve bir öncül isim yok; “anyone who” anlamındaki Whoever gerekir. Whomever nesne konumu içindir; “Anyone is found …” ise iki çekimli fiille cümleyi bozar."},
  {id:"r-noun-clause-09", sub:"noun-clause", from:["clauses-15"], q:"It is now widely accepted ---- regular physical activity reduces the risk of heart disease.", o:["what","whether","that","which","if"], a:2, e:"“widely accepted” kesin bir bilgiyi bildirir ve ardından tam bir cümle gelir: that. whether/if belirsizlik anlatır; what ardından eksik öğeli bir cümle isterdi."},
  {id:"r-noun-clause-10", sub:"noun-clause", from:["w4-08"], q:"What makes the discovery particularly important ----.", o:["that it could lead to a cheaper treatment for malaria","because it could lead to a cheaper treatment","the fact which it could lead to cheaper treatments","when scientists first announced it in 2019","is that it could lead to a cheaper treatment for malaria"], a:4, e:"“What makes the discovery particularly important” isim cümlesi öznedir ve bir ana fiil bekler; yalnızca “is that …” fiil içerir. “that it could lead …” anlamca uygun görünse de fiil eksik kaldığı için cümle tamamlanmaz."},
  {id:"r-noun-clause-11", sub:"noun-clause", from:["clauses-13"], q:"In the survey, participants were asked ---- they had ever been victims of online fraud.", o:["that","what","which","whether","who"], a:3, e:"Evet/hayır cevabı gerektiren dolaylı soru whether ile kurulur. that soru anlamı taşımaz; what ve which ardından eksik öğeli bir yapı isterdi."},
  {id:"r-noun-clause-12", sub:"noun-clause", from:["w3-11"], q:"Nobody could explain ---- the painting had been missing from the gallery for so long without anyone noticing.", o:["what","which","why","whose","whom"], a:2, e:"Boşluktan sonra tam bir cümle var ve anlam nedeni soruyor: why. what, which ve whom ardından eksik öğeli bir cümle isterdi; whose ise ardından bir isim ister."},
  {id:"r-noun-clause-13", sub:"noun-clause", from:["clauses-14","clauses-16"], q:"---- the government decides to do about the housing crisis will affect millions of families.", o:["That","Whether","However","If","Whatever"], a:4, e:"“do” fiilinin nesnesi eksik ve cümle “will affect” fiilinin öznesidir; “anything that” anlamındaki Whatever gerekir. That ve Whether ardından tam bir cümle isterdi."},
  {id:"r-noun-clause-14", sub:"noun-clause", from:["w4-08","clauses-15"], q:"The main problem is ---- we do not have enough reliable data to draw firm conclusions.", o:["what","that","which","so","whose"], a:1, e:"“be” fiilinden sonra tam bir cümle, konuyu açıklayan noun clause olarak that ile gelir. what ardından eksik öğeli bir cümle isterdi; so ise bir sonuç bağlacıdır ve “is” fiilinin tamamlayıcısı olamaz."},
  {id:"r-noun-clause-15", sub:"noun-clause", from:["w3-11","clauses-13"], passage:"Almost everyone dreams every night, even if they cannot remember their dreams in the morning. Yet scientists have long disagreed about (1) ---- humans dream at all. Some argue that dreaming helps the brain process emotions and consolidate memories, while others believe that dreams are simply a by-product of random brain activity during sleep.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["why","what","that","if","whose"], a:0, e:"Boşluktan sonra tam bir cümle var ve devamındaki açıklamalar rüyanın nedenini tartışıyor: why. “at all” ifadesi what'ı dışarıda bırakır; edattan sonra if ve that tek başına gelemez."},
  {id:"r-noun-clause-16", sub:"noun-clause", from:["clauses-14","w4-08"], passage:"When European explorers reached Easter Island in 1722, they found a small population living among nearly a thousand giant stone statues. (1) ---- happened to the society that built these monuments has long puzzled historians. Some blame deforestation and overpopulation, while others argue that diseases brought by the Europeans were the main cause of decline.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["What","That","Whether","How","Which"], a:0, e:"“happened” fiilinin öznesi eksiktir ve cümle “has puzzled” fiilinin öznesidir: What. That, Whether ve How ardından tam bir cümle isterdi."},
  {id:"r-noun-clause-17", sub:"noun-clause", from:["clauses-15"], passage:"For a long time, insects were thought to be incapable of complex visual tasks. (1) ---- honeybees can recognise and remember individual human faces was first demonstrated in a laboratory experiment in 2005. The bees were trained with sugar rewards and were later able to pick out the correct face from several photographs.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["What","If","That","Whether","Which"], a:2, e:"Boşluktan sonra tam bir cümle var ve deneyle kanıtlanmış kesin bir bilgi bildiriliyor: That. Whether belirsizlik bildirir ve “kanıtlandı” anlamıyla çelişir; If özne konumunda kullanılamaz."},
  {id:"r-noun-clause-18", sub:"noun-clause", from:["clauses-13"], q:"---- the new drug is effective depends largely on ---- patients take it at the right time of day.", o:["If / if","That / what","What / whether","Whether / whether","Whether / what"], a:3, e:"Her iki boşlukta da belirsizlik bildiren tam cümleler var; özne konumunda ve edattan (on) sonra yalnızca whether kullanılır. what ardından eksik öğeli bir cümle isterdi, oysa “take it” nesnesi tamdır."},
  {id:"r-noun-clause-19", sub:"noun-clause", from:["w3-11"], q:"Fire investigators are still trying to determine ---- the fire started on the night of the explosion.", o:["what","which","whom","whose","where"], a:4, e:"Boşluktan sonra tam bir cümle var ve dolaylı soru yangının başladığı yeri soruyor: where. what, which ve whom ardından eksik öğeli bir cümle isterdi."},
  {id:"r-noun-clause-20", sub:"noun-clause", from:["w4-08","clauses-14"], q:"---- surprised the organisers most was the number of young people who attended the event.", o:["That","What","It","Which","Whether"], a:1, e:"“surprised” fiilinin öznesi eksik ve cümlenin tamamı “was” fiilinin öznesidir: What (= the thing that). That ve Whether ardından tam bir cümle isterdi; “It” ise iki çekimli fiili bağlayamaz."},
  {id:"r-noun-clause-21", sub:"noun-clause", from:["clauses-13"], q:"It remains to be seen ---- the ceasefire will hold once international observers leave the region.", o:["that","what","whether","which","who"], a:2, e:"“It remains to be seen” sonucu belirsiz bir durumu anlatır; tam cümleden önce whether gerekir. that kesinlik bildirir; what ve which ardından eksik öğeli bir yapı isterdi."},
  {id:"r-noun-clause-22", sub:"noun-clause", from:["w3-11"], q:"The official report does not explain ----.", o:["why was the project abandoned after only two years","what the project was abandoned after only two years","the reason which the project was abandoned","that why the project was abandoned","why the project was abandoned after only two years"], a:4, e:"Noun clause içinde soru kelimesinden sonra düz sıra kullanılır: why the project was abandoned. “why was the project” devrik soru sırasıdır; what ise tam cümleden önce gelemez."},
  {id:"r-noun-clause-23", sub:"noun-clause", from:["w3-11","clauses-14"], q:"Nobody knows exactly ---- people lived in the city at its peak, but estimates range from 50,000 to 100,000.", o:["how much","how many","what","that","whose"], a:1, e:"“people” sayılabilen bir isimdir ve sayı sorulmaktadır: how many. how much sayılamayan isimler içindir; what ardından eksik öğeli bir cümle isterdi."},
  {id:"r-noun-clause-24", sub:"noun-clause", from:["clauses-15"], q:"The idea ---- intelligence is fixed at birth has been seriously challenged by recent research.", o:["which","what","whether","that","of which"], a:3, e:"“the idea / the belief / the claim” gibi isimlerden sonra içeriği açıklayan tam cümle that ile gelir. which relative pronoun olarak eksik öğeli cümle isterdi, oysa “intelligence is fixed at birth” tam bir cümledir."},
  {id:"r-noun-clause-25", sub:"noun-clause", from:["clauses-14","w4-08"], q:"---- the minister said at the press conference contradicted ---- his spokesperson had announced earlier that day.", o:["What / what","That / that","What / that","That / what","Which / what"], a:0, e:"“said” ve “announced” fiillerinin nesneleri eksiktir; her iki boşlukta da the thing that anlamındaki what gerekir. that ardından tam bir cümle isterdi."},
  {id:"r-noun-clause-26", sub:"noun-clause", from:["clauses-14"], q:"Participants were not told ---- group they had been assigned to, which helped prevent bias in the results.", o:["that","whose","whether","which","who"], a:3, e:"Boşluktan sonra bir isim (group) geliyor ve belirli seçenekler arasından hangisi olduğu soruluyor: which group. whether ardından isim değil tam cümle ister; whose ise iyelik bildirir."},
  {id:"r-noun-clause-27", sub:"noun-clause", from:["w3-11"], q:"Ecologists were surprised by ---- quickly the forest recovered after the devastating fire.", o:["what","how","that","so","which"], a:1, e:"Boşluktan sonra bir zarf (quickly) geliyor; derece bildiren how + zarf yapısı gerekir. that edattan sonra tek başına gelemez; what ise bir zarfı nitelemez."},
  {id:"r-ger-inf-01", sub:"ger-inf", from:["clauses-18"], q:"The government has decided to postpone ---- the new fuel tax until the economy shows signs of recovery.", o:["introducing","to introduce","introduce","to introducing","introduced"], a:0, e:"postpone fiili gerund (V-ing) alır: postpone introducing. to introduce, decide gibi to-infinitive alan fiillerle karıştırılan çeldiricidir."},
  {id:"r-ger-inf-02", sub:"ger-inf", from:["clauses-17"], q:"Despite the economic crisis, the small company managed ---- its profits by entering new markets.", o:["increasing","increase","to increase","to increasing","having increased"], a:2, e:"manage fiili to-infinitive alır: managed to increase. increasing ise avoid/consider gibi -ing alan fiillerle karıştırılan çeldiricidir."},
  {id:"r-ger-inf-03", sub:"ger-inf", from:["clauses-19"], q:"After climbing for four hours, the hikers stopped ---- a short rest before the final ascent.", o:["taking","take","having taken","to taking","to take"], a:4, e:"stop + to V bir şeyi yapmak için durmak demektir; yürüyüşçüler dinlenmek için durmuştur. stop + V-ing ise bir eylemi bırakmak anlamına gelir ve bağlama uymaz."},
  {id:"r-ger-inf-04", sub:"ger-inf", from:["clauses-19","clauses-18"], q:"After years of heavy smoking, he finally stopped ---- when his doctor warned him about the risk of lung disease.", o:["to smoke","smoke","to have smoked","smoking","having been smoked"], a:3, e:"stop + V-ing bir alışkanlığı bırakmak demektir: stopped smoking. stop + to V ise “sigara içmek için durdu” anlamına gelir ve doktorun uyarısıyla çelişir."},
  {id:"r-ger-inf-05", sub:"ger-inf", from:["clauses-19"], q:"We regret ---- you that your application for the research fellowship has been unsuccessful.", o:["informing","to inform","inform","to informing","having informed"], a:1, e:"regret + to V resmi dilde kötü bir haberi “üzülerek bildirmek” anlamındadır. regret + V-ing ise geçmişte yapılmış bir şeyden pişmanlık duymak demektir."},
  {id:"r-ger-inf-06", sub:"ger-inf", from:["clauses-18"], q:"Many governments are committed to ---- renewable energy more affordable for low-income households.", o:["make","to make","making","made","have made"], a:2, e:"be committed to kalıbındaki “to” bir edattır ve ardından V-ing gelir: committed to making. “to make” to'yu infinitive sanmaktan doğan tipik bir tuzaktır."},
  {id:"r-ger-inf-07", sub:"ger-inf", from:["clauses-18"], q:"Astronauts on the International Space Station soon get used to ---- in zero gravity.", o:["sleep","slept","have slept","be sleeping","sleeping"], a:4, e:"get / be used to kalıbındaki to bir edattır ve ardından V-ing gelir: get used to sleeping. “used to + V” geçmişteki alışkanlığı anlatan farklı bir yapıdır."},
  {id:"r-ger-inf-08", sub:"ger-inf", from:["clauses-17"], q:"The new regulations will force companies ---- their carbon emissions every year.", o:["reporting","to report","report","to reporting","reported"], a:1, e:"force + nesne + to V kalıbı kullanılır: force companies to report. make gibi yalın fiil ya da V-ing almaz."},
  {id:"r-ger-inf-09", sub:"ger-inf", from:["clauses-17"], q:"Unhappy with the first results, the supervisor made the students ---- the experiment three times.", o:["to repeat","repeating","repeated","repeat","to have repeated"], a:3, e:"make + nesne + yalın fiil (bare infinitive) kalıbı kullanılır: made the students repeat. force/ask gibi fiillerle karıştırılıp seçilen “to repeat” aktif make yapısında yanlıştır."},
  {id:"r-ger-inf-10", sub:"ger-inf", from:["clauses-17"], q:"When journalists raised the issue, the minister refused ---- any questions about the scandal.", o:["to answer","answering","answer","having answered","to answering"], a:0, e:"refuse fiili to-infinitive alır: refused to answer. answering, deny/avoid gibi -ing alan fiillerle karıştırılan çeldiricidir."},
  {id:"r-ger-inf-11", sub:"ger-inf", from:["clauses-20"], q:"The suspect admitted ---- at the scene of the crime, but he denied ---- the victim.", o:["to be / to attack","being / to have attacked","to have been / having attacked","be / attacked","being / having attacked"], a:4, e:"admit ve deny fiilleri gerund alır; saldırı inkârdan önce gerçekleştiği için having attacked uygundur. admit ve deny to-infinitive almadığından “to be” ve “to have attacked” yanlıştır."},
  {id:"r-ger-inf-12", sub:"ger-inf", from:["clauses-18"], q:"When the comedian walked on stage wearing a giant hat, the audience couldn't help ----.", o:["to laugh","laugh","laughed","laughing","to laughing"], a:3, e:"can't help (… -mekten kendini alamamak) kalıbı V-ing alır: couldn't help laughing. to laugh, help fiilinin “yardım etmek” anlamıyla karıştırılan çeldiricidir."},
  {id:"r-ger-inf-13", sub:"ger-inf", from:["clauses-18"], q:"Economists warn that the country risks ---- into recession if oil prices continue to rise.", o:["falling","to fall","fall","fallen","to have fallen"], a:0, e:"risk fiili gerund alır: risks falling. to fall, fiillerin çoğunun to-infinitive aldığını düşünmekten doğan çeldiricidir."},
  {id:"r-ger-inf-14", sub:"ger-inf", from:["clauses-20"], q:"According to early reports, the company appears ---- its annual sales target already, two months before the end of the year.", o:["reaching","to reach","to have reached","having reached","reached"], a:2, e:"appear fiili to-infinitive alır; hedefe şimdiden ulaşılmış olduğu için (already) perfect infinitive gerekir: to have reached. to reach gelecekteki ya da genel bir durumu anlatır; having reached appear ile kullanılmaz."},
  {id:"r-ger-inf-15", sub:"ger-inf", from:["clauses-17"], q:"The old school building needs ---- before it can be used again, as its roof was badly damaged in the storm.", o:["to repair","to be repaired","repair","repaired","being repaired"], a:1, e:"Bina onarılacaktır (pasif); need + to be V3 kalıbı kullanılır: needs to be repaired. to repair aktif anlamla binayı onaran taraf yapar; need fiili “being V3” almaz."},
  {id:"r-ger-inf-16", sub:"ger-inf", from:["clauses-18","clauses-20"], q:"Nobody enjoys ---- by strangers in public places without being asked for permission.", o:["to be photographed","being photographed","photographing","to photograph","be photographed"], a:1, e:"enjoy fiili gerund alır ve “by strangers” eylemin başkasınca yapıldığını gösterir; pasif gerund gerekir: being photographed. photographing aktif anlam verir; enjoy to-infinitive almaz."},
  {id:"r-ger-inf-17", sub:"ger-inf", from:["clauses-19"], q:"“I will never forget ---- the Earth from space for the first time,” the astronaut said in an interview.", o:["to see","see","seen","seeing","to have seen"], a:3, e:"forget + V-ing geçmişte yaşanmış bir deneyimi unutmamak anlamındadır; “for the first time” geçmişteki anıya işaret eder. forget + to V ise yapılması gereken bir işi unutmak demektir."},
  {id:"r-ger-inf-18", sub:"ger-inf", from:["clauses-19"], q:"Before the exam, remember ---- your identity card, as you will not be allowed into the building without it.", o:["bringing","bring","having brought","brought","to bring"], a:4, e:"remember + to V yapılması gereken bir işi unutmamak demektir; kimlik henüz getirilmemiştir. remember + V-ing ise geçmişte yapılmış bir şeyi hatırlamayı anlatır."},
  {id:"r-ger-inf-19", sub:"ger-inf", from:["clauses-17"], q:"The new irrigation technology enables farmers ---- crops with far less water than before.", o:["to grow","growing","grow","to growing","grown"], a:0, e:"enable + nesne + to V kalıbı kullanılır: enables farmers to grow. growing ve grow bu kalıba uymaz."},
  {id:"r-ger-inf-20", sub:"ger-inf", from:["clauses-18"], q:"Instead of ---- on fossil fuels, many cities are now investing heavily in solar and wind power.", o:["rely","to rely","relying","relied","being relied"], a:2, e:"Edattan (instead of) sonra fiil V-ing olarak gelir: instead of relying. Edattan sonra to-infinitive ya da yalın fiil kullanılamaz."},
  {id:"r-ger-inf-21", sub:"ger-inf", from:["clauses-20","clauses-18"], q:"Consumer groups have accused the manufacturer of ---- the health risks of the product for years.", o:["conceal","to conceal","concealed","concealing","to have concealed"], a:3, e:"accuse someone of kalıbındaki of bir edattır ve ardından V-ing gelir: accused of concealing. to conceal ve to have concealed edattan sonra kullanılamaz."},
  {id:"r-ger-inf-22", sub:"ger-inf", from:["clauses-17"], q:"After a long debate, the committee agreed ---- the final decision until more evidence was available.", o:["to delay","delaying","delay","to delaying","having delayed"], a:0, e:"agree fiili to-infinitive alır: agreed to delay. delaying, delay fiilinin kendisinin gerund almasıyla karıştırılan çeldiricidir."},
  {id:"r-ger-inf-23", sub:"ger-inf", from:["clauses-18"], q:"Most nutritionists recommend ---- at least eight glasses of water a day during hot weather.", o:["to drink","drink","drinking","drunk","to drinking"], a:2, e:"recommend fiili doğrudan bir fiil aldığında gerund kullanılır: recommend drinking. “recommend to drink” sık yapılan ama yanlış bir kalıptır."},
  {id:"r-ger-inf-24", sub:"ger-inf", from:["clauses-17"], passage:"Procrastination is not simply a matter of laziness. Psychologists have found that many people tend (1) ---- difficult or unpleasant tasks until the last minute because the tasks make them anxious. Delaying the task brings short-term relief, but the stress usually returns, often stronger than before, as the deadline approaches.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["postponing","postpone","to postponing","having postponed","to postpone"], a:4, e:"tend fiili to-infinitive alır: tend to postpone. postponing, postpone fiilinin kendisinin gerund almasıyla karıştırılan çeldiricidir."},
  {id:"r-ger-inf-25", sub:"ger-inf", from:["clauses-17"], passage:"In June 1924, the British climbers George Mallory and Andrew Irvine set out (1) ---- the summit of Mount Everest. They were last seen only a few hundred metres below the top before clouds hid them from view. Whether they actually reached the summit, almost thirty years before the first confirmed ascent, remains one of the great mysteries of mountaineering.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["reaching","to reach","reach","to reaching","having reached"], a:1, e:"set out fiili amaç bildiren to-infinitive alır: set out to reach (… -meye koyuldular). reaching ve having reached bu kalıba uymaz."},
  {id:"r-ger-inf-26", sub:"ger-inf", from:["clauses-18"], passage:"A growing number of companies are experimenting with shorter working hours. After successful trials, several governments are now considering (1) ---- a four-day working week for public-sector employees. Supporters argue that workers who have more time to rest are more productive, while critics worry about the impact on costs and public services.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["to adopt","adopt","to adopting","adopted","adopting"], a:4, e:"consider fiili gerund alır: considering adopting. to adopt, decide/plan gibi to-infinitive alan fiillerle karıştırılan çeldiricidir."},
  {id:"r-ger-inf-27", sub:"ger-inf", from:["clauses-17"], q:"The patient's condition seemed ---- after the operation, but it suddenly worsened two days later.", o:["improving","improve","to improve","being improved","to improving"], a:2, e:"seem fiili to-infinitive alır: seemed to improve. improving ve being improved seem fiiliyle bu şekilde kullanılmaz."},
  {id:"r-comp-01", sub:"comp", from:["cond-18"], q:"The warmer the ocean water becomes, ---- hurricanes tend to be.", o:["more powerful","the more powerful","the most powerful","the powerful","as powerful"], a:1, e:"“The + comparative …, the + comparative …” paralel kalıbı ikinci yarıda da the + comparative ister: the more powerful. the most powerful superlative olduğu için kalıba uymaz."},
  {id:"r-comp-02", sub:"comp", from:["w4-04","cond-18"], q:"The higher a climber ascends on a mountain, ----.", o:["there is less oxygen available in each breath","the least oxygen is available in each breath","so the air becomes thinner and colder","the less oxygen is available in each breath","the fewer oxygen was available in the past"], a:3, e:"“The + comparative …, the + comparative …” kalıbı ikinci yarıda da the + comparative ister: the less oxygen. “there is less oxygen” the olmadan kalıbı bozar; fewer ise sayılamayan isimle (oxygen) kullanılamaz."},
  {id:"r-comp-03", sub:"comp", from:["cond-19"], q:"Online shopping has become ---- popular than it was before the pandemic.", o:["far more","very more","far most","more much","the more"], a:0, e:"Comparative yapıyı (more popular) güçlendirmek için far / much / a lot kullanılır: far more popular. very comparative'i nitelemez; “far most” ise than ile kullanılamaz."},
  {id:"r-comp-04", sub:"comp", from:["cond-20"], q:"The new airport terminal is ---- the old one, and it can handle three times as many passengers.", o:["three times bigger as","as three times big as","three times as bigger than","as big three times as","three times as big as"], a:4, e:"Kat bildiren karşılaştırma “three times + as + sıfat + as” sırasıyla kurulur. as … as içinde comparative (bigger) ya da than kullanılamaz."},
  {id:"r-comp-05", sub:"comp", from:["cond-20","cond-19"], q:"Today's smartphones are ---- than the computers that guided the Apollo spacecraft to the Moon.", o:["millions of times as powerful","as powerful millions of times","millions of times more powerful","millions of times most powerful","more millions of times powerful"], a:2, e:"Cümlede than bulunduğu için “kat + comparative + than” yapısı gerekir: millions of times more powerful than. “as powerful” as … as kalıbı ister ve than ile kullanılamaz."},
  {id:"r-comp-06", sub:"comp", from:["cond-19"], q:"There were ---- road accidents last year than in any previous year on record.", o:["less","least","the fewest","fewer","little"], a:3, e:"accidents sayılabilen çoğul bir isim olduğu için comparative fewer kullanılır. less sayılamayan isimler içindir; the fewest ise superlative olup than ile kullanılamaz."},
  {id:"r-comp-07", sub:"comp", from:["cond-19"], q:"The Pacific is ---- ocean on Earth, covering about a third of the planet's surface.", o:["by far the largest","far larger","the far largest","much larger than","by far larger"], a:0, e:"Tek bir okyanusun diğerleri arasında en büyük olduğu anlatılıyor ve cümlede than yok; superlative gerekir ve “by far” ile güçlendirilir: by far the largest. much larger than ardından karşılaştırılan öğe gelmeliydi."},
  {id:"r-comp-08", sub:"comp", from:["cond-20"], q:"In terms of public acceptance, nuclear power is not nearly as popular ---- solar power.", o:["than","like","as","so","that"], a:2, e:"“not as / not so + sıfat + as” kalıbında ikinci öğe as ile bağlanır: as popular as. than yalnızca comparative biçimlerle kullanılır."},
  {id:"r-comp-09", sub:"comp", from:["cond-18"], q:"Housing prices in the capital are rising ----, making it increasingly difficult for young people to buy a home.", o:["the faster and faster","more fast and more fast","fastest and fastest","as fast as","faster and faster"], a:4, e:"Sürekli artan bir değişim “comparative + and + comparative” ile anlatılır: faster and faster. fast tek heceli olduğu için “more fast” olmaz; as fast as ise karşılaştırılan öğe olmadan eksik kalır."},
  {id:"r-comp-10", sub:"comp", from:["cond-18"], q:"Of the two proposals submitted to the council, the second is clearly ----.", o:["the most practical","the more practical","more practical than","most practical","practicaler"], a:1, e:"İki şey karşılaştırıldığında “of the two” ile the + comparative kullanılır: the more practical. more practical than ardından karşılaştırılan öğe ister; superlative üç ve daha fazla öğe içindir."},
  {id:"r-comp-11", sub:"comp", from:["cond-20"], q:"This year's wheat harvest was almost ---- last year's, despite the severe drought in the spring.", o:["the same size as","the same size than","same size as","the same size like","as same size as"], a:0, e:"Eşitlik “the same + isim + as” kalıbıyla kurulur: the same size as. the same ile than ya da like kullanılmaz; the olmadan “same” da kalıbı bozar."},
  {id:"r-comp-12", sub:"comp", from:["cond-19"], q:"Children who read regularly tend to have ---- vocabularies than those who rarely read.", o:["very larger","many larger","more larger","much largest","much larger"], a:4, e:"Comparative sıfatı (larger) güçlendirmek için much / far kullanılır: much larger. very comparative'i nitelemez; “more larger” çift karşılaştırma hatasıdır."},
  {id:"r-comp-13", sub:"comp", from:["cond-18","w4-04"], q:"The deeper the scientists drilled into the Antarctic ice, ---- the samples they recovered were.", o:["older","the older","the oldest","the more old","as old"], a:1, e:"“The + comparative …, the + comparative …” kalıbı ikinci yarıda da the + comparative ister: the older. the oldest superlative'dir; old tek heceli olduğu için “more old” kullanılmaz."},
  {id:"r-comp-14", sub:"comp", from:["cond-19"], q:"Ticket prices for the final were ---- expected, so many fans could not afford to attend.", o:["much higher as","very higher than","much high than","much higher than","more higher than"], a:3, e:"much + comparative + than kalıbı gerekir: much higher than. very comparative'i nitelemez; “more higher” çift karşılaştırma hatasıdır."},
  {id:"r-comp-15", sub:"comp", from:["cond-18"], q:"Mount Everest is the highest mountain ---- the world, rising 8,849 metres above sea level.", o:["than","at","in","among","to"], a:2, e:"Superlative bir yer/grup ile birlikte kullanıldığında “in” gelir: the highest mountain in the world. than yalnızca comparative ile kullanılır."},
  {id:"r-comp-16", sub:"comp", from:["cond-18"], q:"The board members agreed that it was ---- decision the company had ever had to make.", o:["more difficult","the more difficult","the most difficult","most difficult than","as difficult"], a:2, e:"“ever had to make” ifadesi tüm kararlar arasında en zor olanı anlatır; superlative gerekir: the most difficult. the more difficult iki öğe arasındaki karşılaştırma içindir."},
  {id:"r-comp-17", sub:"comp", from:["cond-20"], q:"According to government data, women in the country now earn ---- men for doing the same job.", o:["as many as","so much than","as much than","more much than","as much as"], a:4, e:"Sayılamayan bir miktar (kazanç) eşitliği “as much as” ile anlatılır. as many sayılabilen isimler içindir; as … as içinde than kullanılamaz."},
  {id:"r-comp-18", sub:"comp", from:["cond-19"], passage:"For most of human history, the vast majority of people lived in rural areas. Today, however, more than half of the world's population lives in cities, and urban areas are growing (1) ---- than at any other time in history. This rapid growth puts enormous pressure on housing, transport and water supplies, especially in developing countries.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["faster","fastest","more fast","as fast","the faster"], a:0, e:"Cümlede than bulunduğu için comparative gerekir: faster. fast tek heceli olduğu için “more fast” olmaz; fastest ise superlative olup than ile kullanılmaz."},
  {id:"r-comp-19", sub:"comp", from:["cond-18","w4-04"], passage:"Public transport systems face a constant challenge in growing cities. Planners have long observed a simple rule: (1) ---- people live in a city, the greater the demand for buses, trams and underground trains. As a result, cities that fail to invest in public transport often suffer from severe traffic congestion.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["More","The more","The most","As many","The much"], a:1, e:"Cümlenin devamında “the greater” bulunduğu için paralel kalıbın ilk yarısı da the + comparative olmalıdır: The more people. The most superlative olduğu için bu kalıba uymaz."},
  {id:"r-comp-20", sub:"comp", from:["cond-19"], passage:"Car manufacturers are under pressure to reduce the environmental impact of their vehicles. The latest model from one leading company is slightly more expensive than its predecessor, but it consumes (1) ---- fuel, which means lower costs for drivers in the long run. Engineers achieved this mainly by using lighter materials.", blank:1, q:"(1) numaralı boşluğa uygun ifadeyi seçiniz.", o:["considerably fewer","very less","considerably least","considerably less","more less"], a:3, e:"fuel sayılamayan bir isim olduğu için less kullanılır ve considerably ile güçlendirilir: considerably less. fewer sayılabilen isimler içindir; very comparative'i nitelemez."},
  {id:"r-comp-21", sub:"comp", from:["w4-04","cond-18"], q:"The sooner a software problem is identified, ----.", o:["it will be easier to fix","the easiest it will be to fix","so it will be much easier to fix","the more easily it was fixed last time","the easier it will be to fix"], a:4, e:"“The + comparative …, the + comparative …” kalıbı ikinci yarıda da the + comparative ister: the easier. “it will be easier” the olmadan kalıbı bozar; the easiest superlative'dir."},
  {id:"r-comp-22", sub:"comp", from:["cond-18"], q:"Life expectancy in Japan is among ---- in the world, at over 84 years.", o:["the higher","the highest","higher","highest than","the most high"], a:1, e:"“among … in the world” en yüksekler arasında olmayı anlatır; superlative gerekir: the highest. high tek heceli olduğu için “the most high” kullanılmaz."},
  {id:"r-comp-23", sub:"comp", from:["cond-20"], q:"The second edition of the dictionary contains ---- entries as the first.", o:["twice as much","as twice many","twice more","twice as many","two times many"], a:3, e:"Kat bildiren karşılaştırma “twice + as + many/much + as” sırasıyla kurulur; entries sayılabildiği için many: twice as many. as much sayılamayan isimler içindir; “twice more” ise as ile uyuşmaz."},
  {id:"r-comp-24", sub:"comp", from:["cond-19"], q:"Recycling aluminium uses about 95 per cent ---- energy than producing it from raw materials.", o:["less","fewer","least","lesser","the less"], a:0, e:"energy sayılamayan bir isimdir ve than ile karşılaştırılır: less energy than. fewer sayılabilen isimler için kullanılır; least superlative olduğu için than ile gelmez."},
  {id:"r-comp-25", sub:"comp", from:["cond-18"], q:"The more we learn about the human brain, ---- we realise how little we actually understand.", o:["more","the most","the more","the much","so more"], a:2, e:"“The more …, the more …” paralel kalıbı ikinci yarıda da the + comparative ister: the more we realise. the most superlative olduğu için kalıba uymaz."},
  {id:"r-comp-26", sub:"comp", from:["cond-18","cond-19"], q:"The humanitarian situation is becoming ---- serious as more refugees arrive at the border every day.", o:["more and more","the more and more","most and most","much and much","more and most"], a:0, e:"Sürekli artan bir durum “more and more + sıfat” ile anlatılır: more and more serious. Bu yapıda the kullanılmaz; superlative biçimler de bu kalıba girmez."},
  {id:"r-comp-27", sub:"comp", from:["cond-20"], q:"Although the two cities have roughly the same population, the northern city has only ---- public parks as the southern one.", o:["half as much","as half many","half more","half as many","half many as"], a:3, e:"Kat bildiren karşılaştırma “half + as + many/much + as” sırasıyla kurulur; parks sayılabildiği için many: half as many. as much sayılamayan isimler içindir."}
);
